import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>
#include <float.h>

// Approximate GELU
__device__ __forceinline__ float gelu(float x) {
    // 0.5 * x * (1 + tanh( sqrt(2/pi)*(x + 0.044715*x^3) ))
    const float c = 0.044715f;
    const float sqrt_2_over_pi = 0.7978845608f; // sqrt(2.0 / M_PI)
    float x_cubed = x * x * x;
    float inner = sqrt_2_over_pi * (x + c * x_cubed);
    return 0.5f * x * (1.0f + tanhf(inner));
}

// Kernel for fused matmul + GELU
__global__ void matmul_gelu_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ out,
    int batch_size,
    int in_features,
    int out_features
) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;
    if (row < batch_size && col < out_features) {
        float val = 0.0f;
        // Dot product
        for (int i = 0; i < in_features; i++) {
            val += x[row * in_features + i] * w[col * in_features + i];
        }
        // Add bias
        val += b[col];
        // GELU
        val = gelu(val);
        out[row * out_features + col] = val;
    }
}

torch::Tensor fused_matmul_gelu_cuda(
    torch::Tensor x,
    torch::Tensor w,
    torch::Tensor b
) {
    // x: [batch_size, in_features]
    // w: [out_features, in_features]
    // b: [out_features]
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = w.size(0);

    auto out = torch::zeros({batch_size, out_features}, x.options());

    dim3 block(16, 16);
    dim3 grid((batch_size + block.x - 1) / block.x,
              (out_features + block.y - 1) / block.y);

    matmul_gelu_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        in_features,
        out_features
    );

    return out;
}

// Kernel for custom row-wise softmax
__global__ void softmax_kernel(
    float* __restrict__ data,
    int batch_size,
    int out_features
) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < batch_size) {
        // Find max for numerical stability
        float max_val = -FLT_MAX;
        for (int j = 0; j < out_features; j++) {
            float v = data[row * out_features + j];
            max_val = fmaxf(max_val, v);
        }
        // Compute exp and sum
        float sum_val = 0.0f;
        for (int j = 0; j < out_features; j++) {
            float v = __expf(data[row * out_features + j] - max_val);
            data[row * out_features + j] = v;
            sum_val += v;
        }
        // Normalize
        for (int j = 0; j < out_features; j++) {
            data[row * out_features + j] /= sum_val;
        }
    }
}

torch::Tensor custom_softmax_cuda(
    torch::Tensor x
) {
    // x: [batch_size, out_features]
    auto batch_size = x.size(0);
    auto out_features = x.size(1);

    dim3 block(256);
    dim3 grid((batch_size + block.x - 1) / block.x);

    softmax_kernel<<<grid, block>>>(x.data_ptr<float>(), batch_size, out_features);

    return x;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_matmul_gelu_cuda", &fused_matmul_gelu_cuda, "Fused Matmul + GELU (CUDA)");
    m.def("custom_softmax_cuda", &custom_softmax_cuda, "Custom Softmax (CUDA)");
}
"""

fused_ops_header = r"""
torch::Tensor fused_matmul_gelu_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor b);
torch::Tensor custom_softmax_cuda(torch::Tensor x);
"""

# Load the inline extension
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_header,
    cuda_sources=fused_ops_source,
    functions=["fused_matmul_gelu_cuda", "custom_softmax_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
)

class ModelNew(nn.Module):
    """
    Optimized model that replaces the matrix multiplication, GELU, and Softmax 
    with custom CUDA kernels.
    """
    def __init__(self, in_features, out_features):
        super(ModelNew, self).__init__()
        # We replicate the linear layer parameters manually
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(out_features))

    def forward(self, x):
        # Custom fused matmul + GELU
        out = fused_ops.fused_matmul_gelu_cuda(x, self.weight, self.bias)
        # Custom softmax
        out = fused_ops.custom_softmax_cuda(out)
        return out
